static int process_json_payload_append_attributes(
            struct flb_log_event_encoder *encoder,
            msgpack_object *source_map)
{
    int                 result;
    int                 entry_index;
    msgpack_object_map *map;

    result = FLB_EVENT_ENCODER_SUCCESS;

    if (source_map == NULL || source_map->type != MSGPACK_OBJECT_MAP) {
        return result;
    }

    map = &source_map->via.map;

    entry_index = find_map_entry_by_key(map, "attributes", 0, FLB_TRUE);

    if (entry_index >= 0 &&
        map->ptr[entry_index].val.type == MSGPACK_OBJECT_ARRAY) {
        result = flb_log_event_encoder_append_string(
